    processor 6502
    seg code
    org $F000
; ==============================================================================
; Bank6 - the GAMEPLAY CAVE KERNEL (HERO-style; plans/hero_style_kernel_plan.md)
; ------------------------------------------------------------------------------
; Entered from bank0's VBL tail (`sta $1FFA` at GoKernel6; the byte after it is
; `jmp Kernel6Entry` here). Runs the whole 144-line cave, then hands over to the
; bank1 HUD through the fold pad at $FC68 (bytes live in table page $FC).
;
; Everything below `include "generated/cave_kernel.inc"` is GENERATED by
; tools/cave_kernel_gen.py (every scanline is a cycle-exact timeline, asserted at
; generation time). The sprite tables are generated from the art in kernel.asm.
;
; Zero page: the kernel-local state lives in bytes that are free while the cave runs
; (bank1-only HUD bytes $E0-$EF, the EnemyRamY window $E2-$E4, VBL/overscan scratch).
; See the table at KernelZP below; the contract is documented in
; plans/hero_style_kernel_plan.md.
; ==============================================================================

; power-up stub (mandatory in EVERY bank: F4 powers up in an undefined bank)
    lda #0
    sta $1FF4                       ; select bank0 - the fetch at $F005 is its jmp GameStart

; ------------------------------------------------------------------ TIA / RIOT
VSYNC   = $00
VBLANK  = $01
WSYNC   = $02
NUSIZ0  = $04
NUSIZ1  = $05
COLUP0  = $06
COLUP1  = $07
COLUPF  = $08
COLUBK  = $09
CTRLPF  = $0A
PF0     = $0D
PF1     = $0E
PF2     = $0F
GRP0    = $1B
GRP1    = $1C
ENAM0   = $1D
ENAM1   = $1E
ENABL   = $1F
VDELP0  = $25
VDELP1  = $26
INTIM   = $0284

; ----------------------------------------------- bank0 state read by the prologue
RoomY       = $81
Grp0Ptr     = $86           ; player frame pointer (PickPlayerFrame)
CollisionX  = $8B           ; 24 + tide offset (VBL)
CollisionCellY = $8D        ; door stripe colour ($80 = no door)
BombPacked  = $B5
ObjBase     = $B6           ; GRP1 design offset ($FF = none)
ObjTop      = $BB           ; RoomY-relative top of the GRP1 object (+1)
RoomBandColor = $BC
LaserState  = $C0
PF0B        = $C3           ; PF0Buf / PF1Buf / PF2Buf / BandTab / ColupfBuf: 4 bytes per band
PF1B        = $C7
PF2B        = $CB
BandTab     = $CF
CPFB        = $D3
LINES_PER_TILE = 36

; ------------------------------------------------------------------- KernelZP
; Kernel-local bytes (all free while the cave runs; bank0 restages what it needs).
G0      = $EA               ; (zp),Y pointers: lo = segment offset, hi = table page
C0      = $EC
G1      = $EE
C1      = $E5
NextS0  = $E0
NextC0  = $E1
NextS1  = $E2
T       = $E3
M       = $E4
BandCol = $E7
BandColNext = $E8
Band    = $E9
E0      = $84
E1      = $86               ; (Grp0Ptr is read before this is written)
P0Kb    = $87
P1Kb    = $88
TideOff = $89
WaterOff = $8B              ; (CollisionX is read before this is written)
WaterCol = $8C
DoorAnd = $8E
DoorOr  = $8F
P1Top   = $92
P0Top   = RoomY             ; the player's first row IS RoomY
Tmp     = $00               ; `bit Tmp` is only a 3-cycle filler (reads TIA $00)

    include "colors.inc"
    include "generated/bank6_equs.inc"
    include "generated/cave_luts.inc"
CaveFrameLo:    .byte <PlayerSpriteA,<PlayerSpriteB,<PlayerWalkA,<PlayerWalkB

; ---------------------------------------------------------------- entry from bank0
    org Kernel6Pad
    jmp Kernel6Entry

Kernel6Entry:
    ; the VBL tail inits the live kernel did right before its timer poll
    lda #1
    sta VDELP0
    lda #0
    sta VDELP1
    sta ENABL

    ; ---- player frame: Grp0Ptr lo -> frame -> table page + K ----
    lda Grp0Ptr
    ldx #3
.frame:
    cmp CaveFrameLo,X
    beq .frameok
    dex
    bpl .frame
    inx                             ; unknown pointer: frame 0
.frameok:
    lda CaveFrameGHi,X
    sta G0+1
    lda CaveFrameKb,X
    sta P0Kb
    lda #CAVE_P0CHI
    sta C0+1

    ; ---- object: ObjBase -> design -> pages + K, its first row's line ----
    lda ObjBase
    cmp #$FF
    beq .noobj
    ldx #CAVE_NDESIGN-1
.design:
    cmp CaveDesignOff,X
    beq .designok
    dex
    bpl .design
.noobj:
    lda #200                        ; parked: far outside every segment
    sta P1Top
    ldx #0
    beq .pages
.designok:
    lda ObjTop
    clc
    adc RoomY
    sec
    sbc #1                          ; ObjTop = line of row 0 - RoomY + 1
    sta P1Top
.pages:
    lda CaveDesignGHi,X
    sta G1+1
    lda CaveDesignCHi,X
    sta C1+1
    lda CaveDesignKb,X
    sta P1Kb

    ; ---- door stripe: BandCol = (ColupfBuf & DoorAnd) | DoorOr ----
    lda CollisionCellY
    bmi .nodoor
    sta DoorOr
    lda #0
    sta DoorAnd
    beq .doordone
.nodoor:
    lda #$FF
    sta DoorAnd
    lda #0
    sta DoorOr
.doordone:

    ; ---- water: tide offset, band colour (not during the explosion blink) ----
    lda CollisionX
    sec
    sbc #LINES_PER_TILE-12
    sta TideOff
    lda BombPacked
    and #%00000011
    cmp #2
    beq .nowater                    ; blink: COLUBK keeps its blink colour
    lda RoomBandColor
    beq .nowater                    ; band off
    sta WaterCol
    lda #0
    sta WaterOff
    beq .waterdone
.nowater:
    lda #$30                        ; the water store goes to a dead TIA address
    sta WaterOff
.waterdone:

    include "generated/cave_prologue.inc"   ; pointers, segment 0/1, prime, Band = 0

    ; ---- wait for the VBL timer, then start the kernel (one blank line first) ----
.wait:
    lda INTIM
    bne .wait
    sta WSYNC
    lda #0
    sta VBLANK
    sta WSYNC
    jmp BandPad

    include "generated/cave_kernel.inc"

; ---------------------------------------------------- hand-off to the bank1 HUD
; The kernel's last line falls through here at cycle 0 of the first HUD line. Live
; kernel reached the HUD pad at cycle 33; MenuMain's first PF store must keep landing
; at cycle 47, so the nops make up the difference.
KernelExit:
    lda #0
    sta ENABL
    sta ENAM1                       ; end the whole-cave M1 latch
    nop
    nop
    nop
    nop
    nop
    nop
    nop
    nop
    nop
    nop
    nop
    jmp $FC68                       ; fold pad (in table page $FC): lda #1 / sta $1FF5 / jmp $F540

    include "generated/cave_tables.inc"

    org $FFFA
    .word $F000
    .word $F000
    .word $F000
